/**
 * Custom running-status spinner — browser half (Web client module).
 *
 * Two things live here:
 *
 *   1. An icon override. It replaces the mask source of the icon in the
 *      running row ("深度求索中，用时 xx 秒") and resizes its box. The shipped
 *      DOM, its `display` gating, the static SVG fallback and the
 *      reduced-motion / forced-colors behaviour all stay as the host wrote
 *      them — only the mask image and the box edge change.
 *
 *   2. A settings row. The override is useless if the style is frozen in the
 *      bundle, so the same file registers a row into `settings.general.item`
 *      (Settings -> General) that picks the artwork and edits the size live,
 *      with a preview. Both persist in localStorage.
 *
 * Why CSS instead of a slot for the icon: the running row
 * (`RunningStatus` -> `RunningWhaleTail` in `@deepseek-ai/dsh-client-ui-chat`)
 * is rendered straight from ChatView, not through a slot, so no
 * `ctx.slots.register` target exists for it. Its *settings* surface, by
 * contrast, is a real mainline slot, so that half is a normal plugin
 * contribution.
 *
 * Colour keeps coming from `currentColor`, inherited from the "深度求索中" row,
 * so themes and `--dsw-alias-label-deep-diving` keep working.
 *
 * Several styles, each with its own geometry
 * ------------------------------------------
 * The region below holds a list, not a single artwork, and every entry carries
 * its own edge and recommended size. There is no global "the icon size": a
 * 160px raster and a 96px raster cannot share one ceiling without one of them
 * being either wasted or upscaled. So the size range is a property of the
 * selected style, and switching styles re-ranges the slider.
 *
 * The stored value separates the two halves of that: which style, and how big.
 * A `null` size means "whatever this style recommends", which is what makes
 * Reset mean something useful — after a Reset, switching styles gives each one
 * its own default rather than dragging the previous style's number along.
 *
 * Why the icon box is enlarged at all
 * -----------------------------------
 * The shipped icon is 14px with `contain: strict; overflow: hidden`. The
 * artwork is a 160px raster, so at a 14px box one output pixel averages
 * roughly 11x11 = 131 source pixels and anything finer than a blob is gone. The
 * recommended size is 80px, where that same raster lands exactly 1:1 on a 2x
 * display and nothing is resampled at all — the sharpest the browser can draw
 * it. Every style derives its recommendation the same way, from its own edge.
 *
 * Why the artwork is a palette PNG
 * --------------------------------
 * A mask reads the alpha channel only, so a grayscale+alpha PNG spends half its
 * bytes on a luma plane nobody reads. Indexing instead, plus tRNS, carries the
 * same alpha in a fraction of the bytes. The shipped styles use four alpha
 * levels because at the delivered icon size 4, 16 and 256 levels are
 * indistinguishable; the steps only show at the full edge length. The palette is
 * deliberately grayscale — entry i is colour (v, v, v) with alpha v — so masking
 * by alpha and masking by luminance give the identical result and the artwork
 * cannot break if an engine picks the other mode.
 *
 * One sheet, and one property that moves
 * --------------------------------------
 * The sheet declares the artwork once, on `:root`, and references it from the
 * icon and the preview cell — writing the payload into both rules would double
 * it. That declaration is the *fallback* style, and it is what renders if this
 * module's JS never runs: without it a masked element whose `--sc-mask` is
 * undefined would compute to no mask at all and paint as a solid block.
 *
 * The selected style then overrides `--sc-mask` inline on the document element,
 * which is written only when the selection changes. Resizing is a second
 * property and touches no rule. So nothing is ever rewritten at runtime: two
 * custom properties carry the whole state.
 *
 * Module table
 * ------------
 * The factory receives the loader's synchronous require. Only platform seed
 * words may be requested (they are the frozen table the shell shares), and the
 * two used here are both baseline: react and the client store.
 *
 * The artwork is inlined by tools/embed-asset.mjs into the marked region below;
 * do not hand-edit that region.
 */
window.__ModuleLoader__.load({
  id: '@local/spinner-custom',
  factory(require) {
    // --- platform handles --------------------------------------------------
    // Baseline words only; `require` throws at materialization on anything that
    // is neither a seed word nor a registered package factory, which is the
    // runtime mirror of the build-time externals gate.
    const React = require('react')
    const { createSnapshotStore } = require('@deepseek-ai/dsh-client-store')
    const h = React.createElement

    // --- identity ----------------------------------------------------------
    /** Settings dictionary namespace owned by this plugin. */
    const NS = 'settings.spinnerCustom'
    /** localStorage key. Versioned: a future shape change must not read this one. */
    const SETTINGS_KEY = 'dsh.spinner-custom.settings.v1'

    // ===================== generated: the artwork ==========================
    // Everything down to the closing banner is written by
    // tools/embed-asset.mjs. Do not hand-edit it: the tool rebuilds this whole
    // region, so anything typed in here is lost on the next run.
    //
    //   node tools/embed-asset.mjs              rebuild from every PNG in asset/
    //   node tools/embed-asset.mjs a.png b.png  rebuild from exactly those
    //   node tools/embed-asset.mjs --clear      empty it again
    //
    // Each entry is one built-in style, and each carries its own geometry. The
    // artwork's edge is that style's ceiling -- past it you would be upscaling --
    // and half the edge is its recommended size, because the raster is a 2x one.
    // Keeping the numbers next to the pixels is what lets styles of different
    // sizes coexist; there is no single answer to "how big should the icon be".
    //
    //   ARTWORKS      the styles, in the order the picker shows them
    //   FALLBACK_ART  the id shown before anything is chosen
    //
    // An empty list is a state, not a fault: `--clear` produces it deliberately, to
    // build a tree with no artwork in it. See the guard at the top of apply().
    //
    // MIN_SIZE is deliberately outside this region: 14px is the host's own
    // footprint, a fact about the app rather than about any artwork, so changing
    // the styles must not move it.
    const ARTWORKS = [
      { id: 'comet-ring', edge: 160, defaultSize: 80, art: '' },
      { id: 'cross', edge: 160, defaultSize: 80, art: '' },
      { id: 'cutout', edge: 160, defaultSize: 80, art: '' },
      { id: 'dots', edge: 160, defaultSize: 80, art: '' },
      { id: 'fold', edge: 160, defaultSize: 80, art: '' },
      { id: 'rounding', edge: 160, defaultSize: 80, art: '' },
      { id: 'spiral', edge: 160, defaultSize: 80, art: '' },
    ]
    const FALLBACK_ART = 'comet-ring'
    // ===================== end generated ===================================

    /** The host's own footprint: the floor, below which the icon would be a lie. */
    const MIN_SIZE = 14

    /** Look one up, or nothing. Ids come from filenames, so this is user input. */
    const artworkById = id => ARTWORKS.find(artwork => artwork.id === id)

    /**
     * The style a fresh install shows. Never simply `ARTWORKS[0]`: the fallback
     * is declared separately so the picker order can change without changing
     * what people see first.
     */
    const FALLBACK = artworkById(FALLBACK_ART) ?? ARTWORKS[0]

    /**
     * An empty region is a state the plugin handles, not a broken one:
     * `--clear` produces it deliberately, to build a publishable tree with no
     * artwork in it. See the guard at the top of apply().
     */
    const hasArtwork = ARTWORKS.length > 0

    /** A payload as a CSS mask source. */
    const maskUrl = artwork => `url("data:image/png;base64,${artwork.art}")`

    /**
     * The icon box: it is `aria-hidden` and wraps the SVG fallback, so it is
     * the only node on the row matching `:has(> svg)`. The second selector is a
     * child-order fallback for browsers without `:has()`. Both out-specify the
     * shipped single-class rules, which matters because matching specificity
     * would leave the result up to which stylesheet the host injects last.
     */
    const ICON_PRIMARY = '[data-chat-running] span[aria-hidden="true"]:has(> svg)'
    const ICON = `${ICON_PRIMARY},\n`
      + '[data-chat-running] > span:last-child > span:first-child'
    /** The shipped animated mask span, i.e. the icon box's first child. */
    const MASK_SPAN = `${ICON_PRIMARY} > span:first-child,\n`
      + '[data-chat-running] > span:last-child > span:first-child > span:first-child'

    /**
     * Capability gate copied from the shipped rules. The override lives inside
     * it so the host keeps its own fallback behaviour for reduced motion and
     * forced colours, rather than being overridden into an enlarged static icon.
     */
    const GATE = '@media (prefers-reduced-motion: no-preference) and (forced-colors: none)'

    /**
     * How wide a picker tile's mark is drawn. Fixed for every style, so the
     * strip does not jump when the selection changes and so the tiles compare
     * *shapes* rather than resolutions — a style on a 96px raster is drawn at
     * the same optical size as one on a 160px raster.
     */
    const TILE_MARK = 22

    // --- stylesheet --------------------------------------------------------
    /**
     * The single sheet, present for as long as the plugin is loaded: the
     * fallback artwork, the icon override, and the settings row's own CSS.
     *
     * The row's class prefix is `sc-`: this sheet is global (a plain bundle has
     * no CSS-module pipeline), so the names must not collide with host classes.
     * The row's metrics mirror ui-chat's PreferenceRow so it sits in the General
     * column without looking imported.
     */
    const FALLBACK_MASK = FALLBACK === undefined ? 'none' : maskUrl(FALLBACK)
    const SHEET_CSS = `
/* ---- the artwork ------------------------------------------------------
   The fallback style, and the only payload the sheet carries. It is what
   renders on its own if the JS below never runs; the selected style overrides
   this inline on the document element. Declared once and referenced three
   times (icon, preview cell, picker tiles) so the bytes are not repeated. */
:root {
  --sc-mask: ${FALLBACK_MASK};
}

/* ---- the icon override ------------------------------------------------
   Measured against the shipped rules, this is the smallest edit that swaps
   the artwork: the box edge changes, and only the mask the host already
   applies to its own span is restated. The host's static SVG fallback stays
   in the DOM, hidden behind the host's own gating, untouched. */
${GATE} {
  ${ICON} {
    width: var(--spinner-custom-size, ${FALLBACK?.defaultSize ?? MIN_SIZE}px);
    height: var(--spinner-custom-size, ${FALLBACK?.defaultSize ?? MIN_SIZE}px);
  }

  ${MASK_SPAN} {
    -webkit-mask: var(--sc-mask) center / 100% 100% no-repeat;
    mask: var(--sc-mask) center / 100% 100% no-repeat;
    -webkit-mask-mode: alpha;
    mask-mode: alpha;
  }
}

/* ---- the settings row ------------------------------------------------- */
.sc-row {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 0;
  border-bottom: 0.5px solid var(--dsw-alias-border-l2);
}
.sc-text { display: flex; flex-direction: column; gap: 4px; }
.sc-title { font-size: 14px; font-weight: 400; line-height: 22px; color: var(--dsw-alias-label-primary); }
.sc-desc { font-size: 12px; font-weight: 400; line-height: 18px; color: var(--dsw-alias-label-tertiary); }
.sc-body { display: flex; flex-wrap: wrap; align-items: center; gap: 16px; }

/* The preview stage stays one fixed size so dragging the slider does not make
   the settings panel jump; the icon inside it is the real, unstyled pixel size. */
.sc-stage {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 176px;
  height: 176px;
  border: 0.5px solid var(--dsw-alias-border-l2);
  border-radius: var(--dsw-radius-md);
  background: var(--dsw-alias-bg-module-platform);
  /* Preview pigment: the same deep-diving tint the running row uses. */
  color: var(--dsw-alias-label-deep-diving, var(--dsw-alias-label-primary));
  overflow: hidden;
}

.sc-cell {
  display: block;
  background: currentColor;
  -webkit-mask: var(--sc-mask) center / 100% 100% no-repeat;
  mask: var(--sc-mask) center / 100% 100% no-repeat;
  -webkit-mask-mode: alpha;
  mask-mode: alpha;
}

.sc-controls { flex: 1 1 260px; min-width: 240px; display: flex; flex-direction: column; gap: 12px; }
.sc-field { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.sc-label {
  flex: none;
  min-width: 52px;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-tertiary);
}

/* The style picker. Tiles rather than a list, because the artwork is the
   thing being chosen and a name for a shape is a poor substitute for it.
   Each tile carries its own payload in --sc-art, so the sheet stays
   single-payload and only the stage follows the selection. */
.sc-styles { display: flex; flex-wrap: wrap; gap: 5px; }
.sc-tile {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0.5px solid var(--dsw-alias-border-l2);
  border-radius: var(--dsw-radius-sm);
  background: var(--dsw-alias-bg-module-platform);
  color: var(--dsw-alias-label-deep-diving, var(--dsw-alias-label-primary));
  cursor: pointer;
}
.sc-tile:hover { border-color: var(--dsw-alias-label-tertiary); }
.sc-tile[aria-checked="true"] {
  border-color: currentColor;
  background: var(--dsw-alias-interactive-bg-hover);
}
.sc-mark {
  display: block;
  width: ${TILE_MARK}px;
  height: ${TILE_MARK}px;
  background: currentColor;
  -webkit-mask: var(--sc-art) center / 100% 100% no-repeat;
  mask: var(--sc-art) center / 100% 100% no-repeat;
  -webkit-mask-mode: alpha;
  mask-mode: alpha;
}

.sc-range {
  flex: 1 1 120px;
  min-width: 120px;
  margin: 0;
  accent-color: var(--dsw-alias-label-deep-diving, var(--dsw-alias-label-primary));
}
.sc-readout {
  flex: none;
  min-width: 54px;
  text-align: right;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-secondary);
  font-variant-numeric: tabular-nums;
}
.sc-reset {
  flex: none;
  padding: 0;
  border: 0;
  background: transparent;
  font: inherit;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-secondary);
  text-decoration: underline;
  cursor: pointer;
}
.sc-reset:hover:not(:disabled) { color: var(--dsw-alias-label-primary); }
.sc-reset:disabled { color: var(--dsw-alias-label-tertiary); cursor: default; text-decoration: none; }
.sc-hint { margin: 0; font-size: 12px; line-height: 18px; color: var(--dsw-alias-label-tertiary); }
`

    // --- value domain -------------------------------------------------------
    /**
     * Read one candidate size, or `null` when it is not a size at all.
     *
     * Only a number or a non-empty numeric string counts. That matters for
     * `null` and `''`, which `Number()` folds to 0 and which would otherwise
     * clamp up to the floor — reading as "the smallest icon" when the entry
     * really means "nothing was ever stored here".
     *
     * @param value - candidate edge length.
     * @returns a whole number of px, or `null`.
     */
    const readSize = (value) => {
      const usable = typeof value === 'number'
        || (typeof value === 'string' && value.trim() !== '')
      if (!usable) return null
      const size = Math.round(Number(value))
      return Number.isFinite(size) ? size : null
    }

    /** Snap a size into the range the given style allows. */
    const clampTo = (artwork, size) =>
      Math.min(artwork.edge, Math.max(MIN_SIZE, size))

    /** The style a state refers to, falling back to the default one. */
    const artworkOf = state => artworkById(state.art) ?? FALLBACK

    /**
     * The edge actually shown: the stored size, or the style's recommendation
     * when nothing was stored. Always clamped, because the selection can change
     * underneath a size that was legal for the previous style.
     */
    const sizeOf = (state) => {
      const artwork = artworkOf(state)
      return clampTo(artwork, state.size === null ? artwork.defaultSize : state.size)
    }

    /**
     * Snap one restored value into the legal domain. localStorage is
     * user-writable and survives upgrades, so a stored value is untrusted
     * input: a stale, hand-edited or foreign entry must degrade to the default
     * rather than to a 0px box or to a mask that is not in this build.
     *
     * @param value - a rehydrated snapshot.
     * @returns `{ art, size }` with both halves known good.
     */
    const sanitize = (value) => {
      const raw = value !== null && typeof value === 'object' ? value : {}
      const art = typeof raw.art === 'string' && artworkById(raw.art) !== undefined
        ? raw.art
        : FALLBACK.id
      // A size out of range is healed on read by sizeOf, so it is left as the
      // number it was rather than clamped here: clamping at this point would
      // silently discard the user's intent if they later switch to a style that
      // would have allowed it.
      return { art, size: readSize(raw.size) }
    }

    /**
     * Field-wise, because `normalize` compares before deciding to write back.
     * A rehydrated snapshot can be anything JSON can express — including `null`,
     * which is what a stored `"null"` produces — so the left side has to be
     * checked for being an object before it is read.
     */
    const sameSettings = (a, b) =>
      a !== null && typeof a === 'object' && a.art === b.art && a.size === b.size

    /**
     * Heal a rehydrated store in place, so a corrupt entry is repaired and
     * written back once rather than re-checked on every read.
     * @param store - the freshly constructed store.
     * @param coerce - its value-domain projection.
     * @returns the same store.
     */
    const normalize = (store, coerce) => {
      const current = store.getSnapshot()
      const next = coerce(current)
      if (!sameSettings(current, next)) store.set(next)
      return store
    }

    // --- settings copy ------------------------------------------------------
    // `t` falls back to the key itself, so a missing entry degrades to a
    // readable key rather than to a blank row.
    const locales = {
      zh: {
        title: '运行图标',
        description: '任务执行时「深度求索中」那一行里的图标。改完即时生效，并记在这台机器上。',
        style: '样式',
        size: '图标大小',
        reset: '恢复默认',
        hint: '宿主原生只有 14px，比这更细的结构在那个边长下会被平均掉。每个样式都是 2 倍图，'
          + '所以在它自己的默认大小下是一比一，最清楚。',
      },
      en: {
        title: 'Running icon',
        description: 'The icon inside the "deep diving" row shown while a task runs. Changes apply immediately and are kept on this machine.',
        style: 'Style',
        size: 'Icon size',
        reset: 'Reset',
        hint: 'The shipped box is 14px, where anything finer than a blob averages away. '
          + 'Every style is a 2x raster, so its own default lands 1:1.',
      },
    }

    // --- the settings row ---------------------------------------------------
    /**
     * Render the General-section preference row: copy, a live preview at the
     * real pixel size, a style picker, and the size slider.
     *
     * The range follows the selected style, because the styles do not share a
     * ceiling — one of them being a 160px raster and another a 96px one is the
     * normal case, not an edge case.
     *
     * @param props - composed slot props: the injected face plus the `t` seat.
     * @returns the row element.
     */
    function SpinnerCustomRow(props) {
      const settings = props.useSpinnerCustomSettings(value => value)
      const t = props.t
      const artwork = artworkOf(settings)
      const size = sizeOf(settings)

      return h('div', { className: 'sc-row', 'data-spinner-custom-row': 'spinner-custom' },
        h('div', { className: 'sc-text' },
          h('div', { className: 'sc-title' }, t('title')),
          h('div', { className: 'sc-desc' }, t('description')),
        ),
        h('div', { className: 'sc-body' },
          // Decorative only: it shows the chosen edge length at its true pixel
          // size, and it follows the selection so the stage doubles as the
          // picker's confirmation. The controls carry the accessible names, so
          // the stage is kept out of the accessibility tree rather than
          // announced as a second, nameless image.
          h('div', { className: 'sc-stage', 'aria-hidden': 'true' },
            h('span', { className: 'sc-cell', style: { width: `${size}px`, height: `${size}px` } }),
          ),
          h('div', { className: 'sc-controls' },
            h('div', { className: 'sc-field' },
              h('span', { className: 'sc-label' }, t('style')),
              h('div', {
                className: 'sc-styles',
                role: 'radiogroup',
                'aria-label': t('style'),
              }, ARTWORKS.map(item => h('button', {
                type: 'button',
                key: item.id,
                role: 'radio',
                className: 'sc-tile',
                'aria-checked': item.id === artwork.id,
                // The id is the shape's name and comes from the filename; it is
                // the one label that needs no translation to be readable.
                'aria-label': item.id,
                title: item.id,
                style: { '--sc-art': maskUrl(item) },
                onClick: () => { props.setSpinnerCustomArt(item.id) },
              }, h('span', { className: 'sc-mark' })))),
            ),
            h('div', { className: 'sc-field' },
              h('span', { className: 'sc-label' }, t('size')),
              h('input', {
                type: 'range',
                className: 'sc-range',
                min: MIN_SIZE,
                max: artwork.edge,
                step: 1,
                value: size,
                'aria-label': t('size'),
                onChange: event => { props.setSpinnerCustomSize(Number(event.target.value)) },
              }),
              h('span', { className: 'sc-readout', 'aria-hidden': 'true' }, `${size} px`),
              h('button', {
                type: 'button',
                className: 'sc-reset',
                disabled: size === artwork.defaultSize,
                onClick: () => { props.resetSpinnerCustomSize() },
              }, t('reset')),
            ),
            h('p', { className: 'sc-hint' }, t('hint')),
          ),
        ),
      )
    }

    return {
      // `slots` for the settings row, `locale` for its copy. The icon override
      // itself needs neither, but the row is the point of this module.
      inject: ['slots', 'locale'],
      apply(ctx) {
        // The generated region can legitimately be empty -- that is what `--clear`
        // produces, and it is how you build a tree with no artwork in it. Doing
        // nothing is the honest response: there is nothing to mask with, and a
        // settings row that picks between no styles is noise. Say so once, then
        // stay out of the host's way entirely.
        if (!hasArtwork) {
          console.info(
            '[spinner-custom] no artwork embedded, so nothing is overridden. '
            + 'Inline some with: node tools/embed-asset.mjs')
          return
        }

        ctx.effect(() => ctx.locale.register(NS, locales), 'spinner-custom: settings copy')

        const settings = normalize(
          createSnapshotStore({ art: FALLBACK.id, size: null }, { persist: { name: SETTINGS_KEY } }),
          sanitize)

        // The applier lives here, not in the row: the row is only mounted while
        // the settings panel is open, and the icon has to be correct whether or
        // not anyone is looking at the panel.
        ctx.effect(() => {
          const tag = document.createElement('style')
          tag.dataset.spinnerCustom = '@local/spinner-custom'
          tag.textContent = SHEET_CSS
          document.head.append(tag)

          const root = document.documentElement
          // The payload is written only when the selection changes. Resizing
          // happens on every input event of the slider, and re-setting a 55 KB
          // custom property sixty times a second during a drag would be work
          // for nothing.
          let paintedArt = null

          const paint = () => {
            const state = settings.getSnapshot()
            const artwork = artworkOf(state)
            root.style.setProperty('--spinner-custom-size', `${sizeOf(state)}px`)
            if (artwork.id !== paintedArt) {
              paintedArt = artwork.id
              root.style.setProperty('--sc-mask', maskUrl(artwork))
            }
          }
          paint()

          const stopSettings = settings.subscribe(paint)

          /**
           * Runtime tuning hook. The icon's only layout cost is its edge length,
           * so the useful experiment is resizing it live rather than reopening
           * settings. Writes go through the same store the row uses, so a
           * change made here persists and the row agrees with it.
           *
           *   __spinnerCustom.state()     // { art, size, px } -- read it this way
           *                               //   size is what is stored (null means
           *                               //   "follow the style's default");
           *                               //   px is the edge actually shown
           *   __spinnerCustom.style('x')  // pick a style by id; returns the id
           *   __spinnerCustom.size(56)    // clamp + write + return; not a getter,
           *                               //   so size() with no argument writes
           *                               //   the default rather than reporting
           *   __spinnerCustom.reset()     // back to the style's own default
           *   __spinnerCustom.node()      // the icon box, to inspect computed style
           */
          const host = {
            state: () => {
              const state = settings.getSnapshot()
              return { art: artworkOf(state).id, size: state.size, px: sizeOf(state) }
            },
            style(id) {
              const next = artworkById(id) ?? FALLBACK
              settings.set({ ...settings.getSnapshot(), art: next.id })
              return next.id
            },
            size(px) {
              const current = settings.getSnapshot()
              const wanted = readSize(px)
              if (wanted === null) return sizeOf(current)
              const next = { ...current, size: clampTo(artworkOf(current), wanted) }
              settings.set(next)
              return sizeOf(next)
            },
            reset() {
              settings.set({ ...settings.getSnapshot(), size: null })
            },
            node() {
              return document.querySelector(ICON_PRIMARY)
            },
          }
          window.__spinnerCustom = host

          return () => {
            stopSettings()
            tag.remove()
            root.style.removeProperty('--spinner-custom-size')
            root.style.removeProperty('--sc-mask')
            if (window.__spinnerCustom === host) delete window.__spinnerCustom
          }
        }, 'spinner-custom: running icon override')

        // One face serves the row; `hooks` members arrive as use<Name> selector
        // hooks and every other member passes through as a plain prop.
        //
        // Writes go through `set`, not `update`: the store's `update` hands its
        // mutator a draft and DISCARDS the return value (it is a void immer
        // recipe), so a spread-and-return there is a silent no-op. `set` is the
        // wholesale path, it is what the previous release already ran on, and
        // the state is two fields — there is nothing for structural sharing to
        // save.
        const face = () => ({
          hooks: { spinnerCustomSettings: settings },
          setSpinnerCustomArt: id => {
            const next = artworkById(id) ?? FALLBACK
            settings.set({ ...settings.getSnapshot(), art: next.id })
          },
          setSpinnerCustomSize: px => {
            // A value that is not a size clears the override rather than
            // keeping the old one, so the row's own garbage-input behaviour is
            // "back to this style's default" — the same place Reset lands.
            const current = settings.getSnapshot()
            const wanted = readSize(px)
            settings.set({
              ...current,
              size: wanted === null ? null : clampTo(artworkOf(current), wanted),
            })
          },
          resetSpinnerCustomSize: () => {
            settings.set({ ...settings.getSnapshot(), size: null })
          },
        })

        // `settings.general.item` is declared at runtime by ui-settings-general's
        // General entry, so the registration has to wait for the declaration
        // rather than run once at activation.
        ctx.slots.inject('settings.general.item', () => ctx.slots.register({
          name: 'settings.general.item',
          id: 'spinner-custom',
          order: 40,
          locale: NS,
          inject: face,
        }, SpinnerCustomRow))
      },
    }
  },
})
